import{_ as t,o as a,c as s,a0 as i}from"./chunks/framework.DTcU_oZa.js";const g=JSON.parse('{"title":"local.netget","description":"","frontmatter":{},"headers":[],"relativePath":"local-netget.md","filePath":"local-netget.md"}'),o={name:"local-netget.md"};function n(d,e,r,l,h,c){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="local-netget" tabindex="-1">local.netget <a class="header-anchor" href="#local-netget" aria-label="Permalink to &quot;local.netget&quot;">​</a></h1><p><code>local.netget</code> is the operator surface for the local NetGet gateway. It is the management interface — where you configure routing, inspect the monad mesh, view logs, and control the gateway.</p><p>It is not a user-facing surface. It is the surface from which you manage all other surfaces.</p><hr><h2 id="what-it-is" tabindex="-1">What it is <a class="header-anchor" href="#what-it-is" aria-label="Permalink to &quot;What it is&quot;">​</a></h2><p>When NetGet is running and OpenResty is configured, <code>local.netget</code> resolves to the NetGet Dashboard app. The same address is also reachable as <code>localhost</code> and <code>127.0.0.1</code>.</p><table tabindex="0"><thead><tr><th>Address</th><th>Resolves to</th></tr></thead><tbody><tr><td><code>local.netget</code></td><td>NetGet Dashboard</td></tr><tr><td><code>localhost</code></td><td>NetGet Dashboard</td></tr><tr><td><code>127.0.0.1</code></td><td>NetGet Dashboard</td></tr></tbody></table><p>The dashboard is served either from a static build (default) or proxied from a local Vite dev server (dev mode).</p><hr><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><p>From <code>local.netget</code> you can:</p><ul><li><strong>Gateway Dashboard</strong> — see which monads are registered, their health, and last heartbeat</li><li><strong>Domains</strong> — add and remove domain → monad routing rules. Changes hot-reload nginx, no restart required</li><li><strong>Logs</strong> — view the main NetGet server activity log</li><li><strong>Frontend mode</strong> — switch between serving a static build or proxying a live Vite dev server</li></ul><hr><h2 id="how-it-is-served" tabindex="-1">How it is served <a class="header-anchor" href="#how-it-is-served" aria-label="Permalink to &quot;How it is served&quot;">​</a></h2><p>NetGet reads <code>~/.get/xConfig.json</code> to decide how to serve the frontend:</p><table tabindex="0"><thead><tr><th>Mode</th><th>What happens</th></tr></thead><tbody><tr><td><code>package-dist</code></td><td>Serves the built UI bundled with the installed netget package</td></tr><tr><td><code>local-dist</code></td><td>Serves a locally built UI from <code>~/.get/dist/</code></td></tr><tr><td><code>dev</code></td><td>Proxies all requests to a Vite dev server (default <code>http://127.0.0.1:5173</code>)</td></tr></tbody></table><p>To change mode, use the NetGet CLI:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>netget → NetGetX → Main Server UI → [select mode]</span></span></code></pre></div><p>Or edit <code>~/.get/xConfig.json</code> directly and regenerate the nginx config.</p><hr><h2 id="dev-mode" tabindex="-1">Dev mode <a class="header-anchor" href="#dev-mode" aria-label="Permalink to &quot;Dev mode&quot;">​</a></h2><p>In dev mode, OpenResty proxies <code>local.netget</code> directly to the Vite dev server. This means:</p><ul><li>HMR (Hot Module Replacement) works — edits appear instantly in the browser</li><li>The Vite server must be running before you visit <code>local.netget</code></li><li>The nginx config must be regenerated with mode <code>dev</code> and reloaded</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># In the frontend_local directory</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Then regenerate and reload nginx via the NetGet CLI</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">netget</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> →</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> NetGetX</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> →</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Main</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> UI</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> →</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Use</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> React</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> App</span></span></code></pre></div><hr><h2 id="the-frontend-app" tabindex="-1">The frontend app <a class="header-anchor" href="#the-frontend-app" aria-label="Permalink to &quot;The frontend app&quot;">​</a></h2><p>The dashboard app that runs at <code>local.netget</code> is built with <code>this.gui</code>. It lives at:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>netget/Typescript/src/htmls/Netget-REACT/frontend_local/</span></span></code></pre></div><p>It connects to the NetGet Express server (default port <code>3432</code>) for all API calls — domain management, log streaming, gateway identity, and monad discovery.</p><hr><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="https://neurons-me.github.io/NRP/Surface-Access-Points-and-Routing" target="_blank" rel="noreferrer">Surface Access Points and Routing</a> — full routing map</li><li><a href="./Architecture.html">Architecture</a> — how NetGet routes requests</li><li><a href="./DomainMap.html">Domain Map</a> — routing table internals</li><li><a href="./Placement.html">Placement</a> — deploying NetGet on a server</li></ul>`,32)])])}const u=t(o,[["render",n]]);export{g as __pageData,u as default};
